shipping.code:
def shipping_cost(total):
    if total >= 500:
        return 0
    return 40

average.code:
def mean_score(scores):
    if not scores:
        return None
    return sum(scores) / len(scores)

tag.code:
def normalize_tag(value):
    cleaned = value.strip().lower()
    if not cleaned:
        return 'untagged'
    return cleaned
